export const successSnippet = `let latestRequestId = 0;

async function search(word) {
  const requestId = ++latestRequestId;
  setLoading(true);
  const results = await searchAPI(word);

  if (requestId !== latestRequestId) {
    return; // 旧请求：不再更新页面
  }

  setResults(results);
  setLoading(false);
}`;
